{"items":[
  {
    "title":"ALLBUS/GGSS 1980",
    "url_or_doi":"https://search.gesis.org/research_data/ZA0934",
    "justification":"Part of the German General Social Survey (ALLBUS) series with questions on historical and political attitudes in the Federal Republic of Germany; fielded in 1980, fitting the Germany/1980s/history focus."
  },
  {
    "title":"ALLBUS/GGSS 1991",
    "url_or_doi":"https://search.gesis.org/research_data/ZA1960",
    "justification":"German General Social Survey wave including items on historical events, political culture, and memory in Germany, collected in 1991 (relevant to 1990s period and post‑reunification historical perspectives)."
  },
  {
    "title":"ALLBUS/GGSS 1992 – Historical Consciousness (Sonderstudie, East and West Germany)",
    "url_or_doi":"https://search.gesis.org/research_data/ZA2227",
    "justification":"Special ALLBUS study explicitly on historical consciousness in East and West Germany; highly relevant to history in Germany in the early 1990s."
  },
  {
    "title":"ALLBUS/GGSS 1994",
    "url_or_doi":"https://search.gesis.org/research_data/ZA2460",
    "justification":"German General Social Survey wave including modules on political and historical attitudes in Germany during the mid‑1990s."
  },
  {
    "title":"ISSP 1994 – Family and Changing Gender Roles II (Germany, Great Britain, United States)",
    "url_or_doi":"https://search.gesis.org/research_data/ZA2620",
    "justification":"International Social Survey Programme wave with Germany, Great Britain (England), and the USA; includes background variables that allow historical-comparative analysis of social roles in the 1990s across these countries."
  },
  {
    "title":"ISSP 2002 – Family and Changing Gender Roles III (Germany, Great Britain, United States, Sweden)",
    "url_or_doi":"https://search.gesis.org/research_data/ZA3880",
    "justification":"ISSP module including Germany, Great Britain, USA, and Sweden; responses in 2002 allow comparative historical analysis of social change at the start of the 2000s for all four requested countries."
  },
  {
    "title":"ISSP 2003 – National Identity II (Germany, Great Britain, United States, Sweden)",
    "url_or_doi":"https://search.gesis.org/research_data/ZA3910",
    "justification":"Covers national identity, historical pride, and views of the past; includes Germany, Great Britain, USA, and Sweden, making it directly relevant to historical attitudes in the early 2000s in all four countries."
  },
  {
    "title":"ISSP 2013 – National Identity III (Germany, Great Britain, United States, Sweden)",
    "url_or_doi":"https://search.gesis.org/research_data/ZA5950",
    "justification":"Later ISSP national identity wave with questions about historical events and national pride; allows long‑term historical comparison including the 2000s and beyond for Germany, Great Britain/England, Sweden, and USA."
  },
  {
    "title":"Eurobarometer 44.3: Cultural Activities, Employment of People with Disabilities, and the Euro, February–April 1996",
    "url_or_doi":"https://search.gesis.org/research_data/ZA2864",
    "justification":"Includes Great Britain, Sweden, Germany; contains items on cultural activities and attitudes that can be used for historical comparison within Europe in the mid‑1990s."
  },
  {
    "title":"Eurobarometer 52.1: Science and Technology, Cultural Information, and Euro, October–November 1999",
    "url_or_doi":"https://search.gesis.org/research_data/ZA3439",
    "justification":"Covers Germany, Great Britain, and Sweden; provides late‑1990s comparative data relevant for studying historical change in cultural and public attitudes at the turn of the millennium."
  }
]}
